mapper.select:
SELECT id, user_id, benefit_code, total_amount, used_amount, expire_time, created_at
FROM user_benefit_quota
WHERE user_id = #{userId}
  AND benefit_code = #{benefitCode}
LIMIT 1
FOR UPDATE

SELECT id, user_id, benefit_code, consume_amount, biz_type, biz_id, created_at
FROM benefit_usage_log
WHERE user_id = #{userId}
  AND benefit_code = #{benefitCode}
  AND biz_type = #{bizType}
  AND biz_id = #{bizId}
LIMIT 1

SELECT um.id, um.user_id, su.username, su.realname, um.plan_id, mp.code AS plan_code, mp.name AS plan_name, um.product_id, mpr.cycle_type, um.start_time, um.end_time, um.status, um.auto_renew, um.created_at FROM user_membership um LEFT JOIN sys_user su ON su.id = um.user_id LEFT JOIN member_plan mp ON mp.id = um.plan_id LEFT JOIN member_product mpr ON mpr.id = um.product_id
AND ( um.user_id LIKE CONCAT('%', #{query.keyword}, '%') OR su.username LIKE CONCAT('%', #{query.keyword}, '%') OR su.realname LIKE CONCAT('%', #{query.keyword}, '%') )
AND um.plan_id = #{query.planId}
AND um.status = #{query.status}
AND um.end_time >= #{query.endTimeStart}
AND um.end_time <= #{query.endTimeEnd}
ORDER BY um.created_at DESC, um.id DESC
